sys_script.script:
(function executeRule(current, previous) {


    var payment = new GlideRecord('x_2223823_apollo_0_paymen');
    payment.initialize();

    payment.setValue('patient', current.getValue('patient'));
    payment.setValue('hospital', current.getValue('hospital'));
    payment.setValue('patient_type', 'opd');

    payment.setValue('amount', current.getValue('consultation_fee'));

    payment.setValue('status', 'succeeded');
    payment.setValue('kind', 'payment');

    payment.setValue('invoice', current.getValue('invoice'));

    // Set the actual Payment Mode choice value here
    payment.setValue('mode', 'online');

    payment.insert();

})(current, previous);
